import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import { CheckCircle, XCircle } from "lucide-react";

import {
  signInWithEmailAndPassword,
  signInWithPopup,
} from "firebase/auth";

import { auth, googleProvider } from "../firebase";

const Login = () => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  const [loading, setLoading] = useState(false);
  const [googleLoading, setGoogleLoading] = useState(false);

  const [popup, setPopup] = useState({
    show: false,
    message: "",
    type: "success",
  });

  const navigate = useNavigate();

  const showPopup = (message, type = "success") => {
    setPopup({ show: true, message, type });

    setTimeout(() => {
      setPopup({ show: false, message: "", type: "success" });
    }, 2200);
  };

  // 🔐 EMAIL LOGIN
  const handleLogin = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      const res = await signInWithEmailAndPassword(auth, email, password);

      const user = res.user;

      localStorage.setItem("userId", user.uid);
      localStorage.setItem("email", user.email);

      showPopup("Welcome back!", "success");
      setTimeout(() => navigate("/dashboard"), 700);
    } catch (err) {
      showPopup(err.message, "error");
    } finally {
      setLoading(false);
    }
  };

  // 🔵 GOOGLE LOGIN
  const handleGoogleLogin = async () => {
    setGoogleLoading(true);

    try {
      const res = await signInWithPopup(auth, googleProvider);

      const user = res.user;

      localStorage.setItem("userId", user.uid);
      localStorage.setItem("email", user.email);
      localStorage.setItem("name", user.displayName || "");

      showPopup("Signed in with Google", "success");
      setTimeout(() => navigate("/dashboard"), 700);
    } catch (err) {
      showPopup("Google login failed", "error");
    } finally {
      setGoogleLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-gray-50 to-gray-100 px-4">

      {/* POPUP */}
      {popup.show && (
        <div
          className={`fixed top-6 left-1/2 -translate-x-1/2 flex items-center gap-2 px-4 py-2 rounded-lg shadow-md border text-sm ${
            popup.type === "success"
              ? "bg-white text-green-700 border-green-100"
              : "bg-white text-red-700 border-red-100"
          }`}
        >
          {popup.type === "success" ? (
            <CheckCircle className="w-4 h-4" />
          ) : (
            <XCircle className="w-4 h-4" />
          )}
          {popup.message}
        </div>
      )}

      {/* CARD */}
      <div className="w-full max-w-md bg-white border border-gray-200 shadow-xl rounded-2xl p-8">

        {/* HEADER */}
        <div className="text-center mb-6">
          <h1 className="text-3xl font-semibold tracking-tight text-gray-900">
            Spendly
          </h1>
          <p className="text-sm text-gray-500 mt-1">
            Smart expense tracking for modern users
          </p>
        </div>

        {/* FORM */}
        <form onSubmit={handleLogin} className="space-y-3">

          <input
            type="email"
            placeholder="Email address"
            value={email}
            required
            onChange={(e) => setEmail(e.target.value)}
            className="w-full px-3 py-2.5 border border-gray-200 rounded-md focus:outline-none focus:ring-2 focus:ring-black"
          />

          <input
            type="password"
            placeholder="Password"
            value={password}
            required
            onChange={(e) => setPassword(e.target.value)}
            className="w-full px-3 py-2.5 border border-gray-200 rounded-md focus:outline-none focus:ring-2 focus:ring-black"
          />

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-black text-white py-2.5 rounded-md hover:bg-gray-900 transition active:scale-[0.99]"
          >
            {loading ? "Signing you in..." : "Sign in"}
          </button>
        </form>

        {/* DIVIDER */}
        <div className="flex items-center my-5">
          <div className="flex-1 h-px bg-gray-200"></div>
          <span className="px-3 text-xs text-gray-400">OR</span>
          <div className="flex-1 h-px bg-gray-200"></div>
        </div>

        {/* GOOGLE BUTTON */}
        <button
          type="button"
          onClick={handleGoogleLogin}
          disabled={googleLoading}
          className="w-full flex items-center justify-center gap-3 border border-gray-200 bg-white py-2.5 rounded-md shadow-sm hover:shadow-md hover:bg-gray-50 transition active:scale-[0.99]"
        >
          <img
            src="https://www.gstatic.com/firebasejs/ui/2.0.0/images/auth/google.svg"
            alt="Google"
            className="w-5 h-5"
          />

          <span className="text-sm font-medium text-gray-700">
            {googleLoading ? "Signing you in..." : "Continue with Google"}
          </span>
        </button>

        {/* FOOTER */}
        <p className="text-sm text-gray-500 text-center mt-6">
          No account?{" "}
          <span
            onClick={() => navigate("/register")}
            className="text-black font-medium cursor-pointer hover:underline"
          >
            Create one
          </span>
        </p>
      </div>
    </div>
  );
};

export default Login;
